/**
 * structureIndex — the bundled seed structures' provenance
 * record (Slice 39, Track A). GENERATED by the track's build
 * tooling from the real fetched files, parsed with the real
 * parser (src/genx/pdb.ts): every count below is that parser's
 * output on the actual bytes, and the SHA-256 is the actual
 * file's hash. public/structures/INDEX.json carries the same
 * data as JSON; scripts/moldata-check.mjs proves the two agree
 * with each other and with the files on disk.
 *
 * The .pdb texts themselves ship as static assets under
 * public/structures/ (the trauma transport pathing precedent);
 * the renderer track fetches and parses them with pdb.ts.
 *
 * Powered by Nirvana
 */

import type { GenxStructureSource } from "./pdb";

export interface BundledStructureMeta {
  id: string;
  name: string;
  source: GenxStructureSource;
  /** Path under public/ — fetch target for the raw PDB text. */
  file: string;
  /** Where the file came from, verbatim. */
  originUrl: string;
  fetchedDate: string;
  sha256: string;
  chains: { id: string; residues: number }[];
  totalResidues: number;
  /** Distinct heme groups (HEM/HEC) — the parser's count. */
  ligands: number;
}

